// Repliers MLS client — real listing inventory.
//
// ─── Why ────────────────────────────────────────────────────────────
// `activeListings`, `daysOnMarket` and `comparables` were previously
// generated by hashing the URL slug. They were deleted rather than
// nulled, because a plausible-looking fake number is worse than an
// absent one. This client is how they come back as REAL figures.
//
// CREA's HPI gives us a regional benchmark — one number per region per
// property type. That supports ~12 honest regions, not 41 honest cities.
// An MLS feed is the only thing that makes CITY-level pages defensible,
// which is the difference between ~200 thin-but-honest pages and ~200
// genuinely competitive ones.
//
// ─── Contract ───────────────────────────────────────────────────────
// Every function returns `null` when REPLIERS_API_KEY is unset or the
// call fails. Callers MUST treat null as "we don't have this" and render
// an honest absence. There is no fallback, no estimate, no default.
//
// ─── Setup ──────────────────────────────────────────────────────────
//   1. Sign up at https://repliers.com and complete the CREA/TRREB data
//      agreement (this is a commercial agreement, not just an API key —
//      board rules govern what may be displayed publicly).
//   2. Set REPLIERS_API_KEY in .env.local and in the Cloud Run env.
//   3. Confirm your agreement permits PUBLIC display of aggregate counts.
//      Most boards permit aggregates; per-listing display (address, photos)
//      is usually restricted to authenticated IDX/VOW surfaces. This client
//      only exposes AGGREGATES for that reason — see `fetchListingStats`.
//
// ⚠️ DO NOT publish individual listings from this feed without confirming
// your board agreement allows it. Aggregate counts are the safe surface.

const BASE_URL = 'https://api.repliers.io';
const TIMEOUT_MS = 8000;

export interface ListingStats {
  /** Count of active listings matching the filter. */
  activeCount: number;
  /** Median days on market across those listings. Null when too few to be meaningful. */
  medianDaysOnMarket: number | null;
  /** Median list price. Null when the sample is too small. */
  medianListPrice: number | null;
  /** How many listings the medians were computed from. */
  sampleSize: number;
  /** When this was fetched. */
  fetchedAt: string;
}

export interface ListingQuery {
  /** City name as the board records it, e.g. "Toronto". */
  city: string;
  /** Repliers propertyType, e.g. "Detached", "Condo Apartment". */
  propertyType?: string;
  minPrice?: number;
  maxPrice?: number;
}

/**
 * Suppression threshold. Below this many listings we return null medians
 * rather than a figure computed from a handful of homes — a "median" of
 * four listings is noise, and publishing it as a market statistic is the
 * same category of error as the hashed numbers this replaces.
 */
const MIN_SAMPLE_FOR_MEDIAN = 8;

export function isRepliersConfigured(): boolean {
  return Boolean(process.env.REPLIERS_API_KEY);
}

function median(nums: number[]): number | null {
  const clean = nums.filter((n) => Number.isFinite(n) && n > 0).sort((a, b) => a - b);
  if (clean.length === 0) return null;
  const mid = Math.floor(clean.length / 2);
  return clean.length % 2 === 0
    ? Math.round((clean[mid - 1] + clean[mid]) / 2)
    : clean[mid];
}

/**
 * Aggregate active-listing stats for a city × type × price band.
 * Returns null when unconfigured or on any failure — never throws to the
 * caller, because a page render must not depend on a third-party API
 * being up.
 */
export async function fetchListingStats(q: ListingQuery): Promise<ListingStats | null> {
  const apiKey = process.env.REPLIERS_API_KEY;
  if (!apiKey) return null;

  const params = new URLSearchParams();
  params.set('city', q.city);
  params.set('status', 'A');              // Active
  params.set('resultsPerPage', '200');
  if (q.propertyType) params.set('propertyType', q.propertyType);
  if (q.minPrice) params.set('minPrice', String(q.minPrice));
  if (q.maxPrice) params.set('maxPrice', String(q.maxPrice));

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);

  try {
    const res = await fetch(`${BASE_URL}/listings?${params.toString()}`, {
      headers: {
        'REPLIERS-API-KEY': apiKey,
        'content-type': 'application/json',
      },
      signal: controller.signal,
      // Listing counts move daily; an hour of staleness is acceptable and
      // keeps us far inside rate limits during a full sitemap build.
      next: { revalidate: 3600 },
    });
    clearTimeout(timer);

    if (!res.ok) {
      console.warn(`[repliers] ${res.status} for ${q.city}/${q.propertyType ?? 'any'}`);
      return null;
    }

    const data = await res.json() as any;
    const listings: any[] = Array.isArray(data?.listings) ? data.listings : [];
    // `count` is the total matching the filter server-side; `listings` is
    // the current page. Use count for the headline, the page for medians.
    const activeCount: number = typeof data?.count === 'number' ? data.count : listings.length;

    const sample = listings.length;
    const doms = listings
      .map((l) => Number(l?.daysOnMarket ?? l?.dom))
      .filter((n) => Number.isFinite(n));
    const prices = listings
      .map((l) => Number(l?.listPrice ?? l?.price))
      .filter((n) => Number.isFinite(n));

    return {
      activeCount,
      medianDaysOnMarket: sample >= MIN_SAMPLE_FOR_MEDIAN ? median(doms) : null,
      medianListPrice: sample >= MIN_SAMPLE_FOR_MEDIAN ? median(prices) : null,
      sampleSize: sample,
      fetchedAt: new Date().toISOString(),
    };
  } catch (e: any) {
    clearTimeout(timer);
    if (e?.name === 'AbortError') {
      console.warn(`[repliers] timeout for ${q.city}`);
    } else {
      console.warn('[repliers] fetch failed:', e?.message);
    }
    return null;
  }
}

/**
 * Map our matrix property-type slugs to Repliers propertyType values.
 *
 * NOTE: these strings are board-specific and MUST be confirmed against a
 * live response before relying on them — an unmatched propertyType
 * silently returns zero listings, which would look like "no inventory"
 * rather than "wrong filter". Verify with:
 *   curl -H "REPLIERS-API-KEY: $KEY" \
 *     "https://api.repliers.io/listings?city=Toronto&resultsPerPage=5" \
 *     | jq '.listings[].details.propertyType'
 */
export const TYPE_SLUG_TO_REPLIERS: Record<string, string> = {
  detached: 'Detached',
  'semi-detached': 'Semi-Detached',
  townhouse: 'Att/Row/Twnhouse',
  condo: 'Condo Apartment',
};

export function repliersTypeFor(slug: string): string | undefined {
  return TYPE_SLUG_TO_REPLIERS[slug];
}
